#include "diagnostics.hpp"
#include "model.hpp"
#include <sstream>

namespace aoe {
std::string RenderDiagnosticsSnapshot(const DiagnosticsSnapshot& s){std::ostringstream out;out<<"SESSION\r\nSession Generation: "<<s.sessionGeneration<<"\r\nLifecycle: "<<s.lifecycle<<"\r\nPID: "<<s.pid<<"\r\nProcess Creation Time: "<<s.processCreationTime<<"\r\nProcess Handle: "<<Hex(s.processHandle)<<"\r\nModule Base: "<<Hex(s.moduleBase)<<"\r\nTarget SHA-256: "<<s.targetSha256<<"\r\nProfile Status: "<<s.profileStatus<<"\r\nProfile: "<<s.profileName<<"\r\nDebugger Attached: "<<(s.debuggerAttached?"YES":"NO")<<"\r\nBreakpoints Installed: "<<(s.breakpointsInstalled?"YES":"NO")<<" (validation threads="<<s.breakpointThreads<<" / "<<s.threadIds.size()<<", slots="<<s.breakpointSlots<<")\r\nRuntime Armed: "<<(s.runtimeArmed?"YES":"NO")<<"\r\nConfigured Auto Arm: "<<(s.configuredAutoArm?"ON":"OFF")<<"\r\nInitial Calls configured: "<<s.initialCalls<<"\r\nObserved Initial Calls: "<<s.observedInitialCalls;out<<"\r\n\r\nAOE READ-ONLY COUNTERS:\r\nInitial0209Count="<<s.initial0209Count<<"\r\nRepeated020ACount="<<s.repeated020ACount<<"\r\nLinked020BCount=UNAVAILABLE (no independent observer)"<<"\r\nSharedOperationHits="<<s.sharedCallSiteHits<<" (validated shared CALL SITE observations; not function entry)"<<"\r\nAoeLifecycleHits="<<s.aoeLifecycleCallSiteHits<<" (0x020A observations at the same validated call site)"<<"\r\nOperationCounterScope=unarmed same-session live validation; natural periodic operations are not Nx repeats"<<"\r\nRequestedRepeatCount="<<s.requestedRepeatCount<<"\r\nCompletedRepeatCount="<<s.completedRepeatCount<<" (validated completed returns; current or last Nx experiment)";if(!s.configurationDetails.empty())out<<"\r\n\r\nCONFIGURATION:\r\n"<<s.configurationDetails;if(!s.lastExperimentDetails.empty())out<<"\r\n\r\nLAST Nx EXPERIMENT:\r\n"<<s.lastExperimentDetails;if(!s.nextExperimentDetails.empty())out<<"\r\n\r\nNEXT Nx EXPERIMENT:\r\n"<<s.nextExperimentDetails;out<<"\r\nThread IDs:";for(auto tid:s.threadIds)out<<' '<<tid;out<<"\r\nResolved Addresses:\r\n";for(const auto& address:s.addresses)out<<address.name<<": TClient.exe+"<<std::uppercase<<std::hex<<address.rva<<" | "<<Hex(address.absolute)<<std::dec<<"\r\n";out<<"Validation Breakpoints (hardware execution):\r\n";for(auto tid:s.threadIds){unsigned covered=0;for(const auto& bp:s.breakpointCoverage)if(bp.validation&&bp.threadId==tid)++covered;out<<"thread "<<tid<<" validation coverage: "<<(covered>=3?"YES":"NO")<<" ("<<covered<<" / 3)\r\n";}for(const auto& bp:s.breakpointCoverage)if(bp.validation)out<<"thread "<<bp.threadId<<" · DR"<<bp.drSlot<<" · TClient.exe+"<<std::uppercase<<std::hex<<bp.rva<<" | "<<Hex(bp.absolute)<<std::dec<<"\r\n";out<<"Replay Breakpoints:\r\n";for(const auto& bp:s.breakpointCoverage)if(bp.replay)out<<"thread "<<bp.threadId<<" · DR"<<bp.drSlot<<" · TClient.exe+"<<std::uppercase<<std::hex<<bp.rva<<" | "<<Hex(bp.absolute)<<std::dec<<"\r\n";out<<"Producer Breakpoint:\r\n";for(const auto& bp:s.breakpointCoverage)if(bp.producer)out<<"thread "<<bp.threadId<<" · DR"<<bp.drSlot<<" · TClient.exe+"<<std::uppercase<<std::hex<<bp.rva<<" | "<<Hex(bp.absolute)<<std::dec<<"\r\n";out<<"Visual Reader Breakpoint:\r\n";for(const auto& bp:s.breakpointCoverage)if(bp.visual)out<<"thread "<<bp.threadId<<" · DR"<<bp.drSlot<<" · TClient.exe+"<<std::uppercase<<std::hex<<bp.rva<<" | "<<Hex(bp.absolute)<<std::dec<<"\r\n";out<<"Inspector Breakpoints:\r\n";for(const auto& bp:s.breakpointCoverage)if(bp.inspector)out<<"thread "<<bp.threadId<<" · DR"<<bp.drSlot<<" · TClient.exe+"<<std::uppercase<<std::hex<<bp.rva<<" | "<<Hex(bp.absolute)<<std::dec<<"\r\n";out<<"Last Session End Reason: "<<(s.lastSessionEndReason.empty()?"none":s.lastSessionEndReason)<<"\r\nLast Auto-Arm Error: "<<(s.lastAutoArmError.empty()?"none":s.lastAutoArmError)<<"\r\nLast Reattach Error: "<<(s.lastReattachError.empty()?"none":s.lastReattachError);if(!s.liveValidationDetails.empty())out<<"\r\n\r\n"<<s.liveValidationDetails;if(!s.experimentDetails.empty())out<<"\r\n\r\n"<<s.experimentDetails;if(!s.runtimeMessage.empty())out<<"\r\n\r\n"<<s.runtimeMessage;if(!s.runtimeError.empty())out<<"\r\n"<<s.runtimeError;return out.str();}
bool DiagnosticsRenderCache::update(const std::string& snapshot,bool userInteracting){latest_=snapshot;if(frozen_||userInteracting||latest_==rendered_)return false;rendered_=latest_;return true;}
bool DiagnosticsRenderCache::setFrozen(bool frozen,std::string& latestToRender){frozen_=frozen;if(frozen_||latest_==rendered_){latestToRender.clear();return false;}rendered_=latest_;latestToRender=rendered_;return true;}
}
